import { Box, Divider, Drawer, Typography } from '@mui/material'
import type { ReactNode, RefObject } from 'react'
import { useCallback, useEffect, useRef } from 'react'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { GithubAuthToolbarButton } from './github_auth_toolbar_button'
import { ThemeModeToggle } from './menu/theme_mode_toggle'

const MOBILE_DRAWER_WIDTH = 300

interface MobileMainWindowProps {
    auth: UseGithubAuthResult
    cardNavigation: ReactNode | null
    isMenuOpen: boolean
    leftPanel: ReactNode
    onCloseMenu: () => void
    rightPanel: ReactNode
    rightPanelContainerRef: RefObject<HTMLDivElement | null>
    showNavigationInCards: boolean
}

/** Mobile window layout with navigation drawer and workspace content. */
export function MobileMainWindow(props: MobileMainWindowProps) {
    const { auth, cardNavigation, isMenuOpen, leftPanel, onCloseMenu } = props
    const { rightPanel, rightPanelContainerRef, showNavigationInCards } = props
    const cardNavigationElementRef = useRef<HTMLDivElement>(null)
    const navigationElementRef = useRef<HTMLDivElement>(null)
    const updateDrawerVisibility = useCallback(() => {
        const isTextView = workspaceViewService.getSnapshot().viewMode === 'text'
        if (navigationElementRef.current) {
            navigationElementRef.current.style.display = isTextView || showNavigationInCards ? 'flex' : 'none'
        }
        if (cardNavigationElementRef.current) {
            cardNavigationElementRef.current.style.display = !isTextView && !showNavigationInCards ? 'block' : 'none'
        }
    }, [showNavigationInCards])
    const handleNavigationElement = useCallback((element: HTMLDivElement | null) => {
        navigationElementRef.current = element
        updateDrawerVisibility()
    }, [updateDrawerVisibility])
    const handleCardNavigationElement = useCallback((element: HTMLDivElement | null) => {
        cardNavigationElementRef.current = element
        updateDrawerVisibility()
    }, [updateDrawerVisibility])

    useEffect(() => {
        updateDrawerVisibility()
        workspaceViewService.addEventListener('changed', updateDrawerVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateDrawerVisibility)
    }, [updateDrawerVisibility])

    return (
        <>
            <Drawer onClose={onCloseMenu} open={isMenuOpen}>
                <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', width: MOBILE_DRAWER_WIDTH }}>
                    <Box sx={{ alignItems: 'center', display: 'flex', justifyContent: 'space-between', p: 1.5 }}>
                        <Typography sx={{ fontWeight: 600 }} variant="body2">Theme</Typography>
                        <ThemeModeToggle />
                    </Box>
                    <Box sx={{ flex: 1, minHeight: 0 }}>
                        <Box ref={handleCardNavigationElement}>{cardNavigation}</Box>
                        <Box ref={handleNavigationElement} sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Divider />
                            <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>{leftPanel}</Box>
                        </Box>
                    </Box>
                    <Divider />
                    <Box component="footer" sx={{ display: 'flex', justifyContent: 'flex-end', p: 1.5 }}>
                        <GithubAuthToolbarButton auth={auth} />
                    </Box>
                </Box>
            </Drawer>
            <Box ref={rightPanelContainerRef} sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>{rightPanel}</Box>
        </>
    )
}

import { Box } from '@mui/material'
import type { ReactNode } from 'react'
import { useEffect, useRef } from 'react'
import { dialogService } from '../../services/dialog_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'

interface MobileLayoutProps {
    content: ReactNode
}

/** Mobile body layout: a single panel that is only visible while the text view mode is active. */
export function MobileLayout(props: MobileLayoutProps) {
    const { content } = props
    const containerRef = useRef<HTMLDivElement>(null)
    const missingContainerReportedRef = useRef(false)

    useEffect(() => {
        const updateVisibility = () => {
            const container = containerRef.current
            if (!container) {
                if (!missingContainerReportedRef.current) {
                    missingContainerReportedRef.current = true
                    dialogService.error(new Error('Missing mobile layout container'), {fallbackMessage: 'Mobile layout could not be displayed'})
                }
                return
            }

            container.style.display = workspaceViewService.getSnapshot().viewMode === 'text' ? 'flex' : 'none'
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [])

    return (
        <Box ref={containerRef} sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'auto' }}>
            <Box sx={{ flex: 1, minWidth: 0, overflow: 'auto' }}>
                {content}
            </Box>
        </Box>
    )
}

import { Box, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useMemo, useState, type ReactNode } from 'react'
import { navigateTo, useAppLocation } from '../../app/app_navigation'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { ConfigPage } from '../config/config_page'
import { useProjectReference } from '../hooks/use_project_reference'
import { ProjectWorkspace } from '../project_workspace'
import { createSearchRegexpAgent, isSearchRegexpAgentAvailable } from '../../services/search/search_regexp_agent'
import { AppMenu } from './menu/app_menu'
import { SearchControl } from './search/search_control'
import { StatusBar } from './status_bar'

interface MainWindowProps {
    auth: UseGithubAuthResult
    toolbarAction: ReactNode
}

/** Main window: owns the global layout and switches between desktop and mobile presentations. */
export function MainWindow(props: MainWindowProps) {
    const { auth, toolbarAction } = props
    const location = useAppLocation()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const [isMenuOpen, setIsMenuOpen] = useState(false)
    const project = useProjectReference()
    const isConfigOpen = location.pathname === '/config'
    const regexpAgent = useMemo(
        () => isSearchRegexpAgentAvailable() ? createSearchRegexpAgent() : undefined,
        [],
    )

    const handleOpenMenu = useCallback(() => {
        setIsMenuOpen(true)
    }, [])

    const handleCloseMenu = useCallback(() => {
        setIsMenuOpen(false)
    }, [])

    const handleOpenConfig = useCallback(() => {
        navigateTo('/config')
    }, [])

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            <AppMenu
                accessToken={auth.accessToken}
                auth={auth}
                extraActions={toolbarAction}
                isGithubAuthenticated={auth.isAuthenticated}
                isMobile={isMobile}
                onOpenConfig={handleOpenConfig}
                onOpenMobileMenu={handleOpenMenu}
                search={<SearchControl isMobile={isMobile} regexpAgent={regexpAgent} />}
            />
            <ProjectWorkspace
                auth={auth}
                isMenuOpen={isMenuOpen}
                key={project ? `${project.id}:${project.branch}` : 'no-project'}
                onLeftPanelInteraction={handleCloseMenu}
            />
            {!isMobile ? <StatusBar /> : null}
            {isConfigOpen ? <ConfigPage hash={location.hash} /> : null}
        </Box>
    )
}

import { AppBar, Box, IconButton, Toolbar } from '@mui/material'
import type { ReactNode } from 'react'
import Menu from 'mdi-material-ui/Menu'
import { DRAG_REGION, NO_DRAG_REGION } from '../drag_region'
import { ThemeToggleButton } from '../theme_toggle_button'
import { isElectron } from '../../../services/electron_lifecycle_bridge'
import { ProjectNameLabel } from './project_name_label'

const MENU_ROW_HEIGHT = 44
const SEARCH_WIDTH = 286
const PROJECT_NAME_MAX_WIDTH = 240
const APPLICATION_ICON_SOURCE = `${import.meta.env.BASE_URL}favicon.svg`

interface MainToolbarProps {
    isMobile: boolean
    mobileAction: ReactNode
    onOpenMenu: () => void
    panel: ReactNode
    search: ReactNode
    tabs: ReactNode
}

/**
 * Top application toolbar; hosts menu tabs, search, and the desktop drag region.
 * Interactive controls opt out of dragging so the remaining row space can move the window.
 */
export function MainToolbar(props: MainToolbarProps) {
    const { isMobile, mobileAction, onOpenMenu, panel, search, tabs } = props

    return (
        <AppBar
            color="default"
            elevation={0}
            position="static"
            sx={{ borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper' }}
        >
            <Toolbar
                disableGutters
                style={DRAG_REGION}
                sx={{ gap: 0.5, height: MENU_ROW_HEIGHT, minHeight: `${MENU_ROW_HEIGHT}px !important`, px: 1.5 }}
                variant="dense"
            >
                {isMobile ? (
                    <IconButton aria-label="Open menu" edge="start" onClick={onOpenMenu} style={NO_DRAG_REGION} sx={{ mr: 1 }}>
                        <Menu />
                    </IconButton>
                ) : null}
                <Box sx={{ alignItems: 'center', display: 'flex', flexShrink: 0 }}>
                    <Box
                        alt="MDÂ² application icon"
                        component="img"
                        src={APPLICATION_ICON_SOURCE}
                        sx={{
                            height: 24,
                            width: 24,
                        }}
                    />
                </Box>
                <Box style={NO_DRAG_REGION} sx={{ alignSelf: 'stretch', display: 'flex', flexShrink: 0 }}>
                    {tabs}
                </Box>
                <Box
                    data-testid="project-name-region"
                    sx={{ alignItems: 'center', display: 'flex', flex: 1, justifyContent: 'center', minWidth: 16, overflow: 'hidden' }}
                >
                    <Box sx={{ maxWidth: PROJECT_NAME_MAX_WIDTH, minWidth: 0 }}>
                        <ProjectNameLabel />
                    </Box>
                </Box>
                {isMobile ? (
                    <Box style={NO_DRAG_REGION}>
                        {mobileAction}
                    </Box>
                ) : null}
                {isMobile ? (
                    <Box style={NO_DRAG_REGION}>
                        {search}
                    </Box>
                ) : (
                    <Box style={NO_DRAG_REGION}>
                        <ThemeToggleButton />
                    </Box>
                )}
                {!isMobile ? (
                    <Box
                        style={NO_DRAG_REGION}
                        sx={{ display: 'flex', flex: `0 0 ${SEARCH_WIDTH}px`, ml: 0.5, minWidth: 180, mr: isElectron() ? '130px' : 0 }}
                    >
                        {search}
                    </Box>
                ) : null}
            </Toolbar>
            <Box style={NO_DRAG_REGION}>
                {panel}
            </Box>
        </AppBar>
    )
}

import SpeedOutlined from '@mui/icons-material/SpeedOutlined'
import { Box, Button, Divider, Popover, Stack, Typography } from '@mui/material'
import { useEffect, useState, type MouseEvent } from 'react'
import type { CodexRateLimitBucket, CodexRateLimitWindow } from '../../data/electron_codex_runtime_bridge'
import { useCodexRateLimits } from '../hooks/use_codex_rate_limits'

const CODEX_RATE_LIMIT_WARNING_PERCENT = 80
const RESET_CLOCK_UPDATE_INTERVAL_MS = 30_000
const POPOVER_WIDTH = 360
const POPOVER_VIEWPORT_MARGIN = 16
const MINUTES_PER_HOUR = 60
const MINUTES_PER_DAY = 1440
const UNIX_MILLISECONDS_THRESHOLD = 1_000_000_000_000

function resetTimeMilliseconds(resetTime: number) {
    return resetTime < UNIX_MILLISECONDS_THRESHOLD ? resetTime * 1000 : resetTime
}

function formatWindowDuration(durationMinutes: number | null) {
    if (durationMinutes === null) return 'Unknown window'
    if (durationMinutes % MINUTES_PER_DAY === 0) {
        const days = durationMinutes / MINUTES_PER_DAY

        return `${days} ${days === 1 ? 'day' : 'days'}`
    }
    if (durationMinutes % MINUTES_PER_HOUR === 0) {
        const hours = durationMinutes / MINUTES_PER_HOUR

        return `${hours} ${hours === 1 ? 'hour' : 'hours'}`
    }

    return `${durationMinutes} minutes`
}

function formatReset(
    resetTime: number | null,
    observedAt: number,
    receivedAt: number,
    currentTime: number,
) {
    if (resetTime === null) return 'Reset unknown'
    const resetMilliseconds = resetTimeMilliseconds(resetTime)
    const localResetTime = receivedAt + resetMilliseconds - observedAt
    const remainingMilliseconds = Math.max(0, localResetTime - currentTime)
    const remainingMinutes = Math.ceil(remainingMilliseconds / 60_000)
    const localTime = new Date(localResetTime).toLocaleString([], {
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        month: 'short',
    })

    return `Resets ${localTime} (${remainingMinutes} min)`
}

function bucketLabel(bucket: CodexRateLimitBucket, index: number) {
    return bucket.limitName?.trim() || bucket.limitId.trim() || `Limit ${index + 1}`
}

function bucketWindows(bucket: CodexRateLimitBucket) {
    return [
        ...(bucket.primary ? [{ label: 'Primary', value: bucket.primary }] : []),
        ...(bucket.secondary ? [{ label: 'Secondary', value: bucket.secondary }] : []),
    ]
}

function bucketHighestUsage(bucket: CodexRateLimitBucket) {
    const percentages = bucketWindows(bucket).map(({ value }) => value.usedPercent)

    return percentages.length > 0 ? Math.max(...percentages) : null
}

function windowDetail(
    label: string,
    window: CodexRateLimitWindow,
    observedAt: number,
    receivedAt: number,
    currentTime: number,
) {
    const reset = formatReset(window.resetsAt, observedAt, receivedAt, currentTime)

    return `${label}: ${Math.round(window.usedPercent)}% used Â· ${formatWindowDuration(window.windowDurationMins)} Â· ${reset}`
}

/** Account-wide Codex rate-limit status. Own subscription stays at this leaf boundary. */
export function CodexRateLimitStatus() {
    const { receivedAt, snapshot, stale } = useCodexRateLimits()
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const [currentTime, setCurrentTime] = useState(Date.now)

    useEffect(() => {
        const interval = setInterval(() => setCurrentTime(Date.now()), RESET_CLOCK_UPDATE_INTERVAL_MS)

        return () => clearInterval(interval)
    }, [])

    if (!snapshot?.available || receivedAt === null || stale) return null
    const visibleBuckets = snapshot.buckets.filter((bucket) => bucketWindows(bucket).length > 0)
    if (visibleBuckets.length === 0) return null
    const highestUsedPercent = Math.max(...visibleBuckets.map((bucket) => bucketHighestUsage(bucket) ?? 0))
    const reached = visibleBuckets.some(({ rateLimitReachedType }) => !!rateLimitReachedType) || highestUsedPercent >= 100
    const nearLimit = !reached && highestUsedPercent >= CODEX_RATE_LIMIT_WARNING_PERCENT
    const statusColor = reached ? 'error.main' : nearLimit ? 'warning.main' : 'text.secondary'
    const roundedHighestPercent = Math.round(highestUsedPercent)
    const openDetails = (event: MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }
    const closeDetails = () => {
        setAnchorElement(null)
    }
    const accessibleState = reached ? ', limit reached' : nearLimit ? ', near limit' : ''

    return (
        <>
            <Button
                aria-label={`Codex usage ${roundedHighestPercent}% used${accessibleState}`}
                onClick={openDetails}
                size="small"
                startIcon={<SpeedOutlined sx={{ fontSize: 14 }} />}
                sx={{ color: statusColor, fontSize: 'inherit', minWidth: 0, p: 0.5, whiteSpace: 'nowrap' }}
            >
                Codex {roundedHighestPercent}% used
            </Button>
            <Popover
                anchorEl={anchorElement}
                anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
                onClose={closeDetails}
                open={!!anchorElement}
                transformOrigin={{ horizontal: 'right', vertical: 'bottom' }}
            >
                <Box
                    sx={{
                        maxHeight: `calc(100vh - ${POPOVER_VIEWPORT_MARGIN}px)`,
                        maxWidth: `calc(100vw - ${POPOVER_VIEWPORT_MARGIN}px)`,
                        overflow: 'auto',
                        width: POPOVER_WIDTH,
                    }}
                >
                    <Box sx={{ p: 2 }}>
                        <Typography component="h2" sx={{ color: 'text.primary', fontWeight: 700 }} variant="subtitle2">
                            Codex account limits
                        </Typography>
                        {reached ? (
                            <Typography color="error.main" role="status" variant="caption">Codex limit reached</Typography>
                        ) : null}
                    </Box>
                    <Divider />
                    <Stack divider={<Divider flexItem />}>
                        {visibleBuckets.map((bucket, index) => (
                            <Stack key={bucket.limitId || index} spacing={0.5} sx={{ p: 2 }}>
                                <Typography sx={{ color: 'text.primary', fontWeight: 600 }} variant="body2">
                                    {bucketLabel(bucket, index)}
                                </Typography>
                                {bucketWindows(bucket).map(({ label, value }) => (
                                    <Typography color="text.secondary" key={label} variant="caption">
                                        {windowDetail(label, value, snapshot.observedAt, receivedAt, currentTime)}
                                    </Typography>
                                ))}
                            </Stack>
                        ))}
                    </Stack>
                </Box>
            </Popover>
        </>
    )
}

import { Box, CircularProgress, Stack } from '@mui/material'
import CloudUploadOutline from 'mdi-material-ui/CloudUploadOutline'
import ContentSaveOutline from 'mdi-material-ui/ContentSaveOutline'
import { useProjectPersistence } from '../hooks/use_project_persistence'
import { useProjectSession } from '../hooks/use_project_session'

/** Status-bar state for local saves and remote pushes. */
export function ProjectSyncStatus() {
    const { hasPendingPush, localSaveState } = useProjectPersistence()
    const { isPushing } = useProjectSession()
    const isSaving = localSaveState === 'saving'

    return (
        <>
            <Stack
                direction="row"
                spacing={0.75}
                sx={{ alignItems: 'center', color: localSaveState === 'saved' ? 'text.secondary' : 'warning.main' }}
            >
                {isSaving ? <CircularProgress aria-label="Saving" color="inherit" size={14} /> : <ContentSaveOutline sx={{ fontSize: 14 }} />}
                <Box component="span">{isSaving ? 'Saving changes...' : localSaveState === 'dirty' ? 'Dirty' : 'Saved locally'}</Box>
            </Stack>
            <Stack
                direction="row"
                spacing={0.75}
                sx={{ alignItems: 'center', color: hasPendingPush || isPushing ? 'warning.main' : 'text.secondary' }}
            >
                {isPushing ? <CircularProgress aria-label="Pushing" color="inherit" size={14} /> : <CloudUploadOutline sx={{ fontSize: 14 }} />}
                <Box component="span">{isPushing ? 'Pushing...' : hasPendingPush ? 'Changes ready to push' : 'Synced'}</Box>
            </Stack>
        </>
    )
}

import { Box, Stack, Typography } from '@mui/material'
import CardsOutline from 'mdi-material-ui/CardsOutline'
import { useProjectState } from '../hooks/use_project_state'

/** Status-bar totals for all project cards and active cards. */
export function CardCountSummary() {
    const { snapshot } = useProjectState()
    const activeCardCount = snapshot?.activeCards.length ?? 0
    const totalCardCount = activeCardCount + (snapshot?.backgroundCards.length ?? 0)

    return (
        <>
            <Stack direction="row" spacing={0.75} sx={{ alignItems: 'center' }}>
                <CardsOutline sx={{ color: 'text.secondary', fontSize: 14 }} />
                <Typography component="span" sx={{ color: 'text.primary', fontSize: 'inherit', fontWeight: 600 }}>
                    {totalCardCount}
                </Typography>
                <Box component="span">cards</Box>
            </Stack>
            <Stack direction="row" spacing={0.75} sx={{ alignItems: 'center' }}>
                <Box sx={{ bgcolor: 'success.main', borderRadius: '50%', height: 7, width: 7 }} />
                <Typography component="span" sx={{ color: 'text.primary', fontSize: 'inherit', fontWeight: 600 }}>
                    {activeCardCount}
                </Typography>
                <Box component="span">active</Box>
            </Stack>
        </>
    )
}

import { Chip } from '@mui/material'
import { useCallback, useEffect, useState } from 'react'

/** Status-bar indicator reflecting active Caps Lock. */
export function KeyboardStatus() {
    const [isCapsLock, setIsCapsLock] = useState(false)

    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        setIsCapsLock(event.getModifierState('CapsLock'))
    }, [])

    const handleKeyUp = useCallback((event: KeyboardEvent) => {
        setIsCapsLock(event.getModifierState('CapsLock'))
    }, [])

    useEffect(() => {
        window.addEventListener('keydown', handleKeyDown)
        window.addEventListener('keyup', handleKeyUp)

        return () => {
            window.removeEventListener('keydown', handleKeyDown)
            window.removeEventListener('keyup', handleKeyUp)
        }
    }, [handleKeyDown, handleKeyUp])

    if (!isCapsLock) return null

    return <Chip color="primary" label="CAPS" size="small" sx={{ fontSize: 10.5, height: 20 }} variant="outlined" />
}

import { Box, Stack } from '@mui/material'
import { useRemoteControlStatus } from './use_remote_control_status'

/** Status-bar strip showing the remote-control connection state: nothing / accepting / connected. */
export function RemoteControlStatusIndicator() {
    const { bridge, status } = useRemoteControlStatus()

    if (!bridge || !status.active) return null

    const isConnected = status.clientCount > 0

    return (
        <Stack direction="row" spacing={0.75} sx={{ alignItems: 'center' }}>
            <Box sx={{ bgcolor: isConnected ? 'success.main' : 'warning.main', borderRadius: '50%', height: 7, width: 7 }} />
            <Box component="span">{isConnected ? 'connected' : 'accepting'}</Box>
        </Stack>
    )
}

import { Button, List, ListItem, ListItemText, Popover, Typography } from '@mui/material'
import { alpha } from '@mui/material/styles'
import Robot from 'mdi-material-ui/Robot'
import { useState, useSyncExternalStore } from 'react'
import { agentConversationService } from '../../services/agents/agent_conversation_service'
import { useActiveActionRuns } from '../hooks/use_action_runs'

function subscribeToRunningAgents(onStoreChange: () => void) {
    return agentConversationService.subscribe(onStoreChange)
}

function getRunningAgentsSnapshot() {
    return agentConversationService.getRunningAgents()
}

/** Shows the number of running agents and lists them in a popover when opened. */
export function RunningAgentsIndicator() {
    const directRunningAgents = useSyncExternalStore(subscribeToRunningAgents, getRunningAgentsSnapshot, getRunningAgentsSnapshot)
    const activeActionRuns = useActiveActionRuns()
    const agents = [
        ...directRunningAgents,
        ...activeActionRuns.map(({ runId, rootActionId }) => ({ id: runId, label: `Action ${rootActionId}` })),
    ]
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)

    const handleOpen = (event: React.MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }

    const handleClose = () => {
        setAnchorElement(null)
    }

    return (
        <>
            <Button
                aria-label={`Running agents: ${agents.length}`}
                onClick={handleOpen}
                size="small"
                startIcon={<Robot sx={{ fontSize: '14px !important' }} />}
                sx={{
                    bgcolor: (theme) => alpha(theme.palette.primary.main, 0.14),
                    borderRadius: 99,
                    color: 'primary.main',
                    fontSize: 11.5,
                    height: 22,
                    minWidth: 0,
                    px: 1.25,
                    '&:hover': { bgcolor: (theme) => alpha(theme.palette.primary.main, 0.22) },
                }}
            >
                {agents.length} {agents.length === 1 ? 'agent' : 'agents'}
            </Button>
            <Popover
                anchorEl={anchorElement}
                anchorOrigin={{ horizontal: 'left', vertical: 'top' }}
                onClose={handleClose}
                open={!!anchorElement}
                transformOrigin={{ horizontal: 'left', vertical: 'bottom' }}
            >
                {agents.length > 0 ? (
                    <List dense>
                        {agents.map((agent) => (
                            <ListItem key={agent.id}>
                                <ListItemText primary={agent.label} />
                            </ListItem>
                        ))}
                    </List>
                ) : (
                    <Typography sx={{ p: 2 }} variant="body2">
                        No agents running
                    </Typography>
                )}
            </Popover>
        </>
    )
}

import { cleanup, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'
import { StatusBar } from './status_bar'

describe('StatusBar', () => {
    afterEach(cleanup)

    it('renders status indicators', () => {
        render(<StatusBar />)

        expect(screen.getByText('Saved locally')).toBeInTheDocument()
        expect(screen.getByText('Synced')).toBeInTheDocument()
        expect(screen.queryByText('INS')).not.toBeInTheDocument()
        expect(screen.queryByText('OVR')).not.toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'Running agents: 0' })).toBeInTheDocument()
        expect(screen.queryByText(/Codex \d+% used/u)).not.toBeInTheDocument()
    })

    it('does not render an editable status input', () => {
        render(<StatusBar />)

        expect(screen.queryByRole('textbox', { name: 'Status' })).toBeNull()
    })
})

import DataUsageOutlined from '@mui/icons-material/DataUsageOutlined'
import { Box, Button, Divider, Popover, Stack, Typography } from '@mui/material'
import { useMemo, useState, type MouseEvent } from 'react'
import {
    DEFAULT_ARCHIVED_FOLDER,
    DEFAULT_PROJECT_FOLDER,
    DEFAULT_RELEASES_FOLDER,
} from '../../data/data_types'
import { projectAgentTokenUsage } from '../../services/agents/agent_usage'
import { AgentUsageDisplay } from '../agents/agent_usage_display'
import { useProjectConfig } from '../hooks/use_project_config'
import { useProjectState } from '../hooks/use_project_state'

/** Status-bar project total with read-only current-version and release detail. */
export function ProjectAgentUsageSummary() {
    const { snapshot } = useProjectState()
    const projectConfig = useProjectConfig()
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`
    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`
    const totals = useMemo(
        () => projectAgentTokenUsage(snapshot, releasesFolder, archivedFolder),
        [archivedFolder, releasesFolder, snapshot],
    )

    const openSummary = (event: MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }

    const closeSummary = () => {
        setAnchorElement(null)
    }

    const versions = [totals.current, totals.archived, ...totals.releases]

    return (
        <>
            <Button
                aria-label="Agent token usage summary"
                onClick={openSummary}
                size="small"
                startIcon={<DataUsageOutlined sx={{ fontSize: 14 }} />}
                sx={{ color: 'text.secondary', fontSize: 'inherit', minWidth: 0, p: 0.5 }}
            >
                {totals.project.totalTokens.toLocaleString('en-US')} tokens
            </Button>
            <Popover
                anchorEl={anchorElement}
                anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
                onClose={closeSummary}
                open={!!anchorElement}
                transformOrigin={{ horizontal: 'right', vertical: 'bottom' }}
            >
                <Box sx={{ minWidth: 360 }}>
                    <Box sx={{ p: 2 }}>
                        <Typography component="h2" sx={{ color: 'text.primary', fontWeight: 700 }} variant="subtitle2">
                            Project agent usage
                        </Typography>
                        <AgentUsageDisplay usage={totals.project} />
                    </Box>
                    <Divider />
                    <Stack divider={<Divider flexItem />}>
                        {versions.map((version) => (
                            <Box key={version.name} sx={{ p: 2 }}>
                                <Typography sx={{ color: 'text.primary', fontWeight: 600 }} variant="body2">{version.name}</Typography>
                                <AgentUsageDisplay usage={version.usage} />
                            </Box>
                        ))}
                    </Stack>
                </Box>
            </Popover>
        </>
    )
}

import { act, cleanup, render, screen } from '@testing-library/react'
import { createRef } from 'react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { AppThemeProvider } from '../../theme/theme_provider'
import { MobileMainWindow } from './mobile_main_window'

const auth: UseGithubAuthResult = {
    accessToken: null,
    errorMessage: null,
    isAuthenticated: false,
    isLoadingUser: false,
    logout: vi.fn(),
    savePersonalAccessToken: vi.fn(),
    status: 'idle',
    user: null,
}

function renderMobileMainWindow(showNavigationInCards: boolean) {
    const rightPanelContainerRef = createRef<HTMLDivElement>()

    return render(
        <AppThemeProvider>
            <MobileMainWindow
                auth={auth}
                cardNavigation={<nav>Board navigation</nav>}
                isMenuOpen
                leftPanel={<nav>Project navigation</nav>}
                onCloseMenu={vi.fn()}
                rightPanel={<main>Project workspace</main>}
                rightPanelContainerRef={rightPanelContainerRef}
                showNavigationInCards={showNavigationInCards}
            />
        </AppThemeProvider>,
    )
}

describe('MobileMainWindow', () => {
    afterEach(() => {
        cleanup()
        workspaceViewService.setViewMode('cards')
    })

    it('shows navigation in the drawer when requested', () => {
        renderMobileMainWindow(true)

        expect(screen.getByText('Project navigation')).toBeInTheDocument()
        expect(screen.getByText('Project workspace')).toBeInTheDocument()
        expect(screen.getByRole('button', { name: /Switch to (dark|light) theme/ })).toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()
    })

    it('hides navigation without hiding workspace content', () => {
        renderMobileMainWindow(false)

        expect(screen.getByText('Project navigation')).not.toBeVisible()
        expect(screen.getByText('Board navigation')).toBeVisible()
        expect(screen.getByText('Project workspace')).toBeInTheDocument()
    })

    it('shows navigation in text view without rerendering it', () => {
        renderMobileMainWindow(false)
        const navigation = screen.getByText('Project navigation')

        act(() => workspaceViewService.setViewMode('text'))

        expect(screen.getByText('Project navigation')).toBe(navigation)
        expect(navigation).toBeVisible()
        expect(screen.getByText('Board navigation')).not.toBeVisible()
    })
})

import { Box, Button, Divider, MenuItem, Tab as MuiTab, Tabs, TextField, ToggleButton, ToggleButtonGroup, Tooltip } from '@mui/material'
import type { SelectChangeEvent } from '@mui/material'
import type { ChangeEvent, MouseEvent as ReactMouseEvent, ReactNode, SyntheticEvent } from 'react'
import { useCallback, useState } from 'react'
import CardsOutline from 'mdi-material-ui/CardsOutline'
import CheckCircleOutline from 'mdi-material-ui/CheckCircleOutline'
import CloudArrowDownOutline from 'mdi-material-ui/CloudArrowDownOutline'
import CloudArrowUpOutline from 'mdi-material-ui/CloudArrowUpOutline'
import Cog from 'mdi-material-ui/Cog'
import ContentSaveOutline from 'mdi-material-ui/ContentSaveOutline'
import FileDocumentPlusOutline from 'mdi-material-ui/FileDocumentPlusOutline'
import FolderOpen from 'mdi-material-ui/FolderOpen'
import TextBoxOutline from 'mdi-material-ui/TextBoxOutline'
import {
    defaultModelForProfile,
    findAgentProfile,
    mergeAgentProfiles,
    PERMISSION_MODE_OPTIONS,
    supportsPermissionMode,
    THINKING_LEVELS,
    validateThinkingLevel,
    validatePermissionMode,
} from '../../../data/agent_profiles'
import { configService } from '../../../services/config/config_service'
import { writeDesktopConfigToBridge } from '../../../services/config/config_persistence'
import { projectSessionService } from '../../../services/project/project_session_service'
import { workspaceViewService, type WorkspaceViewMode } from '../../../services/project/workspace_view_service'
import { workspaceNavigationService } from '../../../services/project/workspace_navigation_service'
import { actionService } from '../../../services/actions/action_service'
import { dialogService } from '../../../services/dialog_service'
import { projectContext } from '../../../data/action_context'
import type { UseGithubAuthResult } from '../../../auth/use_github_auth'
import { useConfigValue, useHasDesktopConfig } from '../../hooks/use_config_value'
import { useProjectState } from '../../hooks/use_project_state'
import { useProjectPersistence } from '../../hooks/use_project_persistence'
import { useProjectConfig } from '../../hooks/use_project_config'
import { useProjectReadOnly } from '../../hooks/use_project_read_only'
import { usePrimaryWorktreeStatus } from '../../hooks/use_worktrees'
import { useWorkspaceView } from '../../hooks/use_workspace_view'
import { ActionEntryPoints } from '../../actions/run/trigger/action_entry_points'
import { MainToolbar } from './main_toolbar'
import { GithubAuthToolbarButton } from '../github_auth_toolbar_button'
import { NO_DRAG_REGION } from '../drag_region'
import { BranchSwitchDialog } from '../project/branch_switch_dialog'
import { CompleteReleaseDialog } from '../project/complete_release_dialog'
import { NewCardDialog } from '../project/new_card_dialog'
import { ProjectOpenDialog } from '../project/project_open_dialog'
import { useProjectToolbarMenuActions } from '../project/use_project_toolbar_menu_actions'
import { Menu } from './menu'
import { BranchMenuSelect } from './branch_menu_select'
import { MenuIconButton } from './menu_icon_button'
import { MenuSelect } from './menu_select'
import { MobileCreateMenu } from './mobile_create_menu'
import { Section } from './section'
import { Tab } from './tab'

type AppMenuTab = 'home' | 'agents'
type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'

interface AppMenuProps {
    accessToken: string | null
    auth: UseGithubAuthResult
    extraActions: ReactNode
    isGithubAuthenticated: boolean
    isMobile: boolean
    onOpenConfig: () => void
    onOpenMobileMenu: () => void
    search: ReactNode
}

const MENU_TABS: { label: string; value: AppMenuTab }[] = [
    { label: 'Home', value: 'home' },
    { label: 'Run', value: 'agents' },
]
const PROJECT_CONTEXT = projectContext()

function persistDesktopConfig() {
    if (!configService.hasDesktopConfig()) return

    writeDesktopConfigToBridge(configService.getDesktopValues())
}

/** Tabbed app menu hosting project, account and agent actions. */
export function AppMenu(props: AppMenuProps) {
    const { accessToken, auth, extraActions, isGithubAuthenticated, isMobile, onOpenConfig, onOpenMobileMenu, search } = props
    const { project } = useProjectState()
    const { hasPendingPush, hasPendingSave } = useProjectPersistence()
    const primaryWorktreeStatus = usePrimaryWorktreeStatus()
    const projectConfig = useProjectConfig()
    const { viewMode } = useWorkspaceView()
    const [currentTab, setCurrentTab] = useState<AppMenuTab>('home')
    const [dialogMode, setDialogMode] = useState<ProjectDialogMode | null>(null)
    const agentProfiles = mergeAgentProfiles(useConfigValue('desktop.agentProfiles'))
    const selectedAgent = useConfigValue('desktop.agent')
    const selectedProfile = findAgentProfile(agentProfiles, selectedAgent)
    const selectedModels = selectedProfile?.models ?? []
    const configuredModel = useConfigValue('desktop.model')
    const selectedThinkingLevel = useConfigValue('desktop.thinkingLevel')
    const selectedPermissionMode = useConfigValue('desktop.permissionMode')
    const desktopAvailable = useHasDesktopConfig()
    const selectedModel = configuredModel || (selectedProfile ? defaultModelForProfile(selectedProfile) : '')
    const projectBranch = project?.branch ?? ''
    const readOnly = useProjectReadOnly()

    const closeDialog = useCallback(() => {
        setDialogMode(null)
    }, [])

    const openDialog = useCallback((mode: ProjectDialogMode) => {
        setDialogMode(mode)
    }, [])

    const actions = useProjectToolbarMenuActions({
        accessToken,
        isGithubAuthenticated,
        onCloseDialog: closeDialog,
        onOpenDialog: openDialog,
    })
    const branchOptions = actions.branches.length > 0 ? actions.branches : (project ? [{ name: project.branch }] : [])
    const selectedBranch = branchOptions.some((branch) => branch.name === actions.switchBranch) ? actions.switchBranch : projectBranch

    const handleTabChange = (_event: SyntheticEvent, value: AppMenuTab) => {
        setCurrentTab(value)
    }

    const handleOpenProject = () => {
        actions.openProjectDialog()
    }

    const handleCreateProjectFolders = (projectFolder: string) => {
        void actions.createProjectFolders(projectFolder)
    }

    const handleLoadBranches = () => {
        void actions.loadSwitchBranches()
    }

    const handleBranchChange = (event: SelectChangeEvent) => {
        void actions.switchProjectBranch(event.target.value)
    }

    const handleOpenReleaseDialog = () => {
        void actions.openReleaseDialog()
    }

    const handleOpenCardDialog = () => {
        actions.openNewCardDialog()
    }

    const handleCommit = async () => {
        try {
            await actions.commit()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handlePush = async () => {
        try {
            await actions.push()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handlePull = async () => {
        try {
            await actions.pull()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const handleViewModeChange = (_event: ReactMouseEvent<HTMLElement>, nextMode: WorkspaceViewMode | null) => {
        if (!nextMode) return

        workspaceViewService.setViewMode(nextMode)
    }

    const handleAgentChange = (event: SelectChangeEvent) => {
        const profile = findAgentProfile(agentProfiles, event.target.value)
        const nextModel = profile ? defaultModelForProfile(profile) : ''
        configService.set('desktop.agent', event.target.value)
        configService.set('desktop.model', nextModel)
        persistDesktopConfig()
    }

    const setModel = (value: string) => {
        configService.set('desktop.model', value)
        persistDesktopConfig()
    }

    const handleModelSelectChange = (event: SelectChangeEvent) => {
        setModel(event.target.value)
    }

    const handleModelTextChange = (event: ChangeEvent<HTMLInputElement>) => {
        setModel(event.target.value)
    }

    const handleThinkingLevelChange = (event: SelectChangeEvent) => {
        const thinkingLevel = validateThinkingLevel(event.target.value, 'Default reasoning level')
        configService.set('desktop.thinkingLevel', thinkingLevel)
        persistDesktopConfig()
    }

    const handlePermissionModeChange = (event: SelectChangeEvent) => {
        const permissionMode = validatePermissionMode(event.target.value, 'Default permission mode')
        configService.set('desktop.permissionMode', permissionMode)
        persistDesktopConfig()
    }

    const handleCreateAction = async () => {
        try {
            if (!projectConfig) throw new Error('Cannot create an action before project config is loaded')

            const { definition, path } = actionService.createDefinition(projectConfig.actionsFolder)
            await actionService.saveDefinition(path, definition)
            workspaceViewService.setViewMode('text')
            workspaceNavigationService.open(path)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action creation failed' })
        }
    }

    const handleDiscardGithubPendingCommits = () => {
        if (!actions.pendingGithubConflictProject) return

        projectSessionService.discardGithubPendingCommits(actions.pendingGithubConflictProject, accessToken)
    }

    const menuTabs = (
        <Tabs
            aria-label="Application menu"
            onChange={handleTabChange}
            scrollButtons={false}
            sx={{
                minHeight: 44,
                '& .MuiTabs-indicator': { height: 2 },
            }}
            value={currentTab}
            variant="scrollable"
        >
            {MENU_TABS.map((tab) => (
                <MuiTab
                    key={tab.value}
                    label={tab.label}
                    sx={{ fontSize: 13.5, minHeight: 44, minWidth: 0, px: 1.5, textTransform: 'none' }}
                    value={tab.value}
                />
            ))}
        </Tabs>
    )

    const viewSection = (
        <Section label="View">
            <ToggleButtonGroup
                exclusive
                onChange={handleViewModeChange}
                size="small"
                sx={{
                    bgcolor: 'action.selected',
                    borderRadius: 1,
                    gap: 0.25,
                    p: 0.375,
                    '& .MuiToggleButtonGroup-grouped': { border: 0, borderRadius: '6px !important', height: 28, px: 1.25 },
                    '& .Mui-selected': { bgcolor: 'background.paper', boxShadow: '0 1px 2px rgba(16,24,40,0.1)' },
                }}
                value={viewMode}
            >
                <Tooltip title="Cards view">
                    <ToggleButton aria-label="Cards view" value="cards">
                        <CardsOutline fontSize="small" />
                        <Box component="span" sx={{ ml: 0.75 }}>Board</Box>
                    </ToggleButton>
                </Tooltip>
                <Tooltip title="Text view">
                    <ToggleButton aria-label="Text view" value="text">
                        <TextBoxOutline fontSize="small" />
                        <Box component="span" sx={{ ml: 0.75 }}>List</Box>
                    </ToggleButton>
                </Tooltip>
            </ToggleButtonGroup>
        </Section>
    )

    const menuPanel = (
        <Menu>
            <Box role="tabpanel" sx={{ display: currentTab === 'home' ? 'block' : 'none' }}>
                <Tab>
                    {isMobile ? (
                        <>
                            {viewSection}
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                        </>
                    ) : null}
                    <Section label="Project">
                        <MenuIconButton label="Open project" onClick={handleOpenProject}>
                            <FolderOpen fontSize="small" />
                        </MenuIconButton>
                        <BranchMenuSelect
                            branches={branchOptions}
                            disabled={!actions.isProjectOpen || actions.isLoading}
                            onChange={handleBranchChange}
                            onOpen={handleLoadBranches}
                            value={selectedBranch}
                        />
                        <MenuIconButton
                            disabled={readOnly || !actions.isProjectOpen || actions.isLoading || !hasPendingSave}
                            label="Commit"
                            onClick={handleCommit}
                        >
                            <ContentSaveOutline fontSize="small" />
                        </MenuIconButton>
                        <MenuIconButton
                            disabled={
                                !actions.isProjectOpen
                                || readOnly
                                || actions.isLoading
                                || (!hasPendingPush && (primaryWorktreeStatus?.ahead ?? 0) <= 0)
                            }
                            label="Push"
                            onClick={handlePush}
                        >
                            <CloudArrowUpOutline fontSize="small" />
                        </MenuIconButton>
                        <MenuIconButton
                            disabled={
                                !actions.isProjectOpen
                                || readOnly
                                || actions.isLoading
                                || hasPendingSave
                                || hasPendingPush
                                || !primaryWorktreeStatus?.hasUpstream
                                || primaryWorktreeStatus.dirty
                                || primaryWorktreeStatus.ahead > 0
                                || primaryWorktreeStatus.behind <= 0
                            }
                            label="Pull"
                            onClick={handlePull}
                        >
                            <CloudArrowDownOutline fontSize="small" />
                        </MenuIconButton>
                    </Section>
                    <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                    <Section label="Settings">
                        <MenuIconButton label="Config" onClick={onOpenConfig}>
                            <Cog fontSize="small" />
                        </MenuIconButton>
                        {extraActions}
                    </Section>
                    {!isMobile ? (
                        <>
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                            {viewSection}
                            <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                            <Button disabled={!project || readOnly} onClick={handleCreateAction} size="small" variant="outlined">New action</Button>
                            <Button
                                disabled={!actions.isProjectOpen || readOnly}
                                onClick={handleOpenCardDialog}
                                size="small"
                                startIcon={<FileDocumentPlusOutline fontSize="small" />}
                                sx={{ height: 34, px: 1.75 }}
                                variant="contained"
                            >
                                New card
                            </Button>
                            <Box sx={{ flex: 1 }} />
                            <Section label="Account">
                                <GithubAuthToolbarButton auth={auth} />
                            </Section>
                        </>
                    ) : null}
                </Tab>
            </Box>
            <Box role="tabpanel" sx={{ display: currentTab === 'agents' ? 'block' : 'none' }}>
                <Tab>
                    <Section label="Setup">
                        <MenuSelect
                            disabled={!desktopAvailable}
                            label="Default agent"
                            minWidth={130}
                            onChange={handleAgentChange}
                            value={selectedAgent}
                        >
                            {agentProfiles.map((profile) => (
                                <MenuItem key={profile.name} value={profile.name}>{profile.name}</MenuItem>
                            ))}
                        </MenuSelect>
                        {selectedModels.length > 0 ? (
                            <MenuSelect
                                disabled={!desktopAvailable}
                                label="Default model"
                                minWidth={150}
                                onChange={handleModelSelectChange}
                                value={selectedModel}
                            >
                                {selectedModels.map((model) => (
                                    <MenuItem key={model} value={model}>{model}</MenuItem>
                                ))}
                            </MenuSelect>
                        ) : (
                            <Tooltip title="Default model">
                                <TextField
                                    disabled={!desktopAvailable}
                                    onChange={handleModelTextChange}
                                    size="small"
                                    slotProps={{ htmlInput: { 'aria-label': 'Default model' } }}
                                    style={NO_DRAG_REGION}
                                    sx={{ width: 150 }}
                                    value={selectedModel}
                                />
                            </Tooltip>
                        )}
                        <MenuSelect
                            disabled={!desktopAvailable}
                            label="Default reasoning level"
                            minWidth={120}
                            onChange={handleThinkingLevelChange}
                            value={selectedThinkingLevel}
                        >
                            {THINKING_LEVELS.map((level) => (
                                <MenuItem key={level} value={level}>{level}</MenuItem>
                            ))}
                        </MenuSelect>
                        {selectedProfile && supportsPermissionMode(selectedProfile) ? (
                            <MenuSelect
                                disabled={!desktopAvailable}
                                label="Default permission mode"
                                minWidth={190}
                                onChange={handlePermissionModeChange}
                                value={selectedPermissionMode}
                            >
                                {PERMISSION_MODE_OPTIONS.map(({ label, value }) => (
                                    <MenuItem key={value} value={value}>{label}</MenuItem>
                                ))}
                            </MenuSelect>
                        ) : <TextField disabled size="small" value="Permissions unsupported" />}
                    </Section>
                    <Divider flexItem orientation="vertical" sx={{ my: 1.5 }} />
                    <Section label="Actions">
                        <ActionEntryPoints context={PROJECT_CONTEXT} variant="icons" visibility="explicit-context" />
                        <MenuIconButton
                            disabled={readOnly || !actions.isProjectOpen || actions.activeCards.length === 0 || actions.isReleaseCompleting}
                            label="Complete release"
                            onClick={handleOpenReleaseDialog}
                        >
                            <CheckCircleOutline fontSize="small" />
                        </MenuIconButton>
                    </Section>
                </Tab>
            </Box>
            <ProjectOpenDialog
                branches={actions.branches}
                initialSource={actions.initialProjectSource}
                isDesktopMode={actions.isDesktopMode}
                isGithubAuthenticated={isGithubAuthenticated}
                isLoading={actions.isLoading}
                onChooseLocalFolder={actions.chooseLocalProjectFolder}
                onCreateProjectFolders={handleCreateProjectFolders}
                projectOpenResolution={actions.projectOpenResolution}
                onBranchChange={() => undefined}
                onClose={actions.closeDialog}
                onCreateRemoteProject={actions.createRemoteProject}
                onCreateWorkingFolder={() => void actions.createWorkingFolder()}
                onDiscardGithubPendingCommits={handleDiscardGithubPendingCommits}
                onLoadManualBranches={actions.loadManualBranches}
                onLoadRemoteBranches={actions.loadRemoteBranches}
                onOpenGithub={actions.openGithubProject}
                onOpenLocal={actions.openLocalProject}
                onOpenRemote={actions.openRemoteProject}
                onRepositoryChange={actions.loadRepositoryBranches}
                onSourceChange={actions.clearOpenDialogState}
                onUseWorkingFolder={(folder) => void actions.openWorkingFolder(folder)}
                open={dialogMode === 'open'}
                pendingGithubConflictProject={actions.pendingGithubConflictProject}
                recentLocalRepositories={actions.recentLocalRepositories}
                repositories={actions.repositories}
            />
            <BranchSwitchDialog
                branches={actions.branches}
                isLoading={actions.isLoading}
                onBranchChange={actions.setSwitchBranch}
                onClose={actions.closeDialog}
                onSwitchBranch={(branch) => void actions.switchProjectBranch(branch)}
                open={dialogMode === 'branch'}
                selectedBranch={actions.switchBranch}
            />
            <CompleteReleaseDialog
                branchCandidates={actions.releaseBranchCandidates}
                defaultSelectAll={actions.releaseSelectAllDefault}
                isLoading={actions.isLoading}
                key={dialogMode === 'release' ? 'release-open' : 'release-closed'}
                onClose={actions.closeDialog}
                onCompleteRelease={actions.completeRelease}
                onSelectAllDefaultChange={actions.setReleaseSelectAllDefault}
                open={dialogMode === 'release'}
            />
            <NewCardDialog
                cardBodyTemplate={actions.cardBodyTemplate}
                cardTypes={actions.cardTypes}
                initialTargetStatus={actions.newCardInitialStatus}
                isLoading={actions.isLoading}
                isProjectOpen={actions.isProjectOpen}
                onClose={actions.closeDialog}
                onCreateCard={actions.createCard}
                open={dialogMode === 'card'}
                states={actions.states}
            />
        </Menu>
    )

    return (
        <MainToolbar
            isMobile={isMobile}
            mobileAction={isMobile && currentTab === 'home' ? (
                <MobileCreateMenu
                    isNewActionDisabled={!project || readOnly}
                    isNewCardDisabled={!actions.isProjectOpen || readOnly}
                    onCreateAction={handleCreateAction}
                    onCreateCard={handleOpenCardDialog}
                />
            ) : null}
            onOpenMenu={onOpenMobileMenu}
            panel={menuPanel}
            search={search}
            tabs={menuTabs}
        />
    )
}

