import { AppBar, Box, IconButton, Toolbar } from '@mui/material'
import type { ReactNode } from 'react'
import Menu from 'mdi-material-ui/Menu'
import { DRAG_REGION, NO_DRAG_REGION } from '../drag_region'
import { ThemeToggleButton } from '../theme_toggle_button'
import { isElectron } from '../../../services/electron_lifecycle_bridge'
import { ProjectNameLabel } from './project_name_label'

const MENU_ROW_HEIGHT = 44
const SEARCH_WIDTH = 286
const PROJECT_NAME_MAX_WIDTH = 240
const APPLICATION_ICON_SOURCE = `${import.meta.env.BASE_URL}favicon.svg`

interface MainToolbarProps {
    isMobile: boolean
    mobileAction: ReactNode
    onOpenMenu: () => void
    panel: ReactNode
    search: ReactNode
    tabs: ReactNode
}

/**
 * Top application toolbar; hosts menu tabs, search, and the desktop drag region.
 * Interactive controls opt out of dragging so the remaining row space can move the window.
 */
export function MainToolbar(props: MainToolbarProps) {
    const { isMobile, mobileAction, onOpenMenu, panel, search, tabs } = props

    return (
        <AppBar
            color="default"
            elevation={0}
            position="static"
            sx={{ borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper' }}
        >
            <Toolbar
                disableGutters
                style={DRAG_REGION}
                sx={{ gap: 0.5, height: MENU_ROW_HEIGHT, minHeight: `${MENU_ROW_HEIGHT}px !important`, px: 1.5 }}
                variant="dense"
            >
                {isMobile ? (
                    <IconButton aria-label="Open menu" edge="start" onClick={onOpenMenu} style={NO_DRAG_REGION} sx={{ mr: 1 }}>
                        <Menu />
                    </IconButton>
                ) : null}
                <Box sx={{ alignItems: 'center', display: 'flex', flexShrink: 0 }}>
                    <Box
                        alt="MDÂ² application icon"
                        component="img"
                        src={APPLICATION_ICON_SOURCE}
                        sx={{
                            height: 24,
                            width: 24,
                        }}
                    />
                </Box>
                <Box style={NO_DRAG_REGION} sx={{ alignSelf: 'stretch', display: 'flex', flexShrink: 0 }}>
                    {tabs}
                </Box>
                <Box
                    data-testid="project-name-region"
                    sx={{ alignItems: 'center', display: 'flex', flex: 1, justifyContent: 'center', minWidth: 16, overflow: 'hidden' }}
                >
                    <Box sx={{ maxWidth: PROJECT_NAME_MAX_WIDTH, minWidth: 0 }}>
                        <ProjectNameLabel />
                    </Box>
                </Box>
                {isMobile ? (
                    <Box style={NO_DRAG_REGION}>
                        {mobileAction}
                    </Box>
                ) : null}
                {isMobile ? (
                    <Box style={NO_DRAG_REGION}>
                        {search}
                    </Box>
                ) : (
                    <Box style={NO_DRAG_REGION}>
                        <ThemeToggleButton />
                    </Box>
                )}
                {!isMobile ? (
                    <Box
                        style={NO_DRAG_REGION}
                        sx={{ display: 'flex', flex: `0 0 ${SEARCH_WIDTH}px`, ml: 0.5, minWidth: 180, mr: isElectron() ? '130px' : 0 }}
                    >
                        {search}
                    </Box>
                ) : null}
            </Toolbar>
            <Box style={NO_DRAG_REGION}>
                {panel}
            </Box>
        </AppBar>
    )
}

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'
import type { AgentConversation, AgentRunEvent } from '../../data/data_types'
import { agentConversationService } from '../../services/agents/agent_conversation_service'
import { RunningAgentsIndicator } from './running_agents_indicator'

const conversation = (runId: string): AgentConversation => ({
    cardPath: null,
    completedAt: null,
    entries: [{ content: '', id: runId, kind: 'message', role: 'user', timestamp: '2026-01-01T00:00:00.000Z' }],
    hasExplicitTitle: true,
    id: runId,
    path: runId,
    providerSessions: [],
    startedAt: '2026-01-01T00:00:00.000Z',
    status: 'running',
    title: 'Run',
    viewed: true,
})

const startedEvent = (runId: string): AgentRunEvent => ({
    conversation: conversation(runId),
    runId,
    type: 'started',
})

const closedEvent = (runId: string): AgentRunEvent => ({
    conversation: { ...conversation(runId), completedAt: '2026-01-01T00:01:00.000Z', status: 'completed' },
    runId,
    type: 'closed',
})

describe('RunningAgentsIndicator', () => {
    afterEach(() => {
        cleanup()
        agentConversationService.observeRunEvent(closedEvent('a'), '')
        agentConversationService.observeRunEvent(closedEvent('b'), '')
    })

    it('reports the running-agent count', () => {
        agentConversationService.observeRunEvent(startedEvent('a'), 'Build')
        agentConversationService.observeRunEvent(startedEvent('b'), 'Lint')
        render(<RunningAgentsIndicator />)

        expect(screen.getByRole('button', { name: 'Running agents: 2' })).toBeInTheDocument()
    })

    it('lists the running agents in a popover', () => {
        agentConversationService.observeRunEvent(startedEvent('a'), 'Build docs')
        render(<RunningAgentsIndicator />)

        fireEvent.click(screen.getByRole('button', { name: 'Running agents: 1' }))

        expect(screen.getByText('Build docs')).toBeInTheDocument()
    })

    it('shows an empty message when no agents run', () => {
        render(<RunningAgentsIndicator />)

        fireEvent.click(screen.getByRole('button', { name: 'Running agents: 0' }))

        expect(screen.getByText('No agents running')).toBeInTheDocument()
    })

    it('updates when direct running agents change', () => {
        render(<RunningAgentsIndicator />)

        act(() => agentConversationService.observeRunEvent(startedEvent('a'), 'Build'))

        expect(screen.getByRole('button', { name: 'Running agents: 1' })).toBeInTheDocument()
    })
})

import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { AgentConversation, Card, ProjectSnapshot } from '../../data/data_types'
import { ProjectAgentUsageSummary } from './project_agent_usage_summary'

const { projectConfig, projectState } = vi.hoisted(() => ({
    projectConfig: {
        archivedFolder: 'design/records/archived',
        projectFolder: 'design',
        releasesFolder: 'design/records/releases',
    },
    projectState: { snapshot: null as ProjectSnapshot | null },
}))

vi.mock('../hooks/use_project_config', () => ({ useProjectConfig: () => projectConfig }))
vi.mock('../hooks/use_project_state', () => ({ useProjectState: () => projectState }))

function conversation(id: string, totalTokens: number): AgentConversation {
    return {
        actionId: null,
        cardInternalId: id,
        cardPath: id,
        completedAt: 'now',
        entries: [],
        hasExplicitTitle: true,
        id,
        path: `logs/${id}.json`,
        providerSessions: [],
        startedAt: 'now',
        status: 'completed',
        title: 'Run',
        viewed: true,
        usage: { cachedInputTokens: 0, inputTokens: totalTokens, outputTokens: 0, reasoningTokens: 0, totalTokens },
    }
}

function card(path: string, totalTokens: number): Card {
    return {
        agentConversationErrors: [],
        agentConversations: [conversation(path, totalTokens)],
        content: '',
        header: {
            affects: [], after: null, agentLogReferences: [], author: null, id: path, internalId: path,
            owner: null, policy: {}, status: 'done', title: path,
        },
        hasFrontmatter:true,
        isActive: !path.includes('/history/'),
        path,
    }
}

describe('ProjectAgentUsageSummary', () => {
    afterEach(() => {
        cleanup()
        projectState.snapshot = null
    })

    it('reads configured archived and release usage details', () => {
        projectState.snapshot = {
            activeCards: [card('design/F-1.md', 16)],
            backgroundCards: [
                card('design/records/releases/v1/F-2.md', 32),
                card('design/records/archived/F-3.md', 8),
            ],
            repositoryFiles: [],
            workingFolder: 'design',
