import {
    getElectronCodexRuntimeBridge,
    type CodexRateLimitSnapshot,
    type ElectronCodexRuntimeBridge,
} from '../../data/electron_codex_runtime_bridge'
import { register } from '../service_injector'

export interface CodexRateLimitState {
    receivedAt: number | null
    snapshot: CodexRateLimitSnapshot | null
    stale: boolean
}

const INITIAL_STATE: CodexRateLimitState = { receivedAt: null, snapshot: null, stale: false }
const UNIX_MILLISECONDS_THRESHOLD = 1_000_000_000_000

function resetTimeMilliseconds(resetTime: number) {
    return resetTime < UNIX_MILLISECONDS_THRESHOLD ? resetTime * 1000 : resetTime
}

function firstResetTime(snapshot: CodexRateLimitSnapshot) {
    const resetTimes = snapshot.buckets.flatMap(({ primary, secondary }) => (
        [primary?.resetsAt, secondary?.resetsAt]
            .filter((resetTime): resetTime is number => resetTime !== null && resetTime !== undefined)
            .map(resetTimeMilliseconds)
    ))

    return resetTimes.length > 0 ? Math.min(...resetTimes) : null
}

function validSnapshot(snapshot: CodexRateLimitSnapshot) {
    return Number.isFinite(snapshot.observedAt)
        && (!snapshot.available || snapshot.buckets.length > 0)
        && snapshot.buckets.every(({ primary, secondary }) => (
            (!primary || Number.isFinite(primary.usedPercent))
            && (!secondary || Number.isFinite(secondary.usedPercent))
        ))
}

/** Owns current account-wide Codex rate limits for this renderer process only. */
export class CodexRateLimitService extends EventTarget {
    private bridge: ElectronCodexRuntimeBridge | null = null
    private expirationTimer: ReturnType<typeof setTimeout> | null = null
    private state: CodexRateLimitState = INITIAL_STATE
    private unsubscribeConnection: (() => void) | null = null
    private unsubscribeRateLimits: (() => void) | null = null

    constructor() {
        super()
        register('codexRateLimitService', this)
    }

    getState() {
        return this.state
    }

    start() {
        const bridge = getElectronCodexRuntimeBridge()
        if (bridge === this.bridge && this.unsubscribeRateLimits) return

        this.unsubscribe()
        this.bridge = bridge
        this.setState(INITIAL_STATE)
        if (!bridge) return

        this.unsubscribeRateLimits = bridge.onCodexRateLimits((snapshot) => this.acceptSnapshot(bridge, snapshot))
        this.unsubscribeConnection = bridge.onConnectionChanged?.((connected) => this.handleConnectionChange(bridge, connected)) ?? null
        void this.refresh(bridge)
    }

    stop() {
        this.unsubscribe()
        this.bridge = null
        this.setState(INITIAL_STATE)
    }

    private acceptSnapshot(bridge: ElectronCodexRuntimeBridge, snapshot: CodexRateLimitSnapshot) {
        if (bridge !== this.bridge || !validSnapshot(snapshot)) return
        const currentObservedAt = this.state.snapshot?.observedAt
        if (currentObservedAt !== undefined && snapshot.observedAt < currentObservedAt) return

        const receivedAt = Date.now()
        this.setState({ receivedAt, snapshot, stale: false })
        this.scheduleExpiration(snapshot, receivedAt)
    }

    private async refresh(bridge: ElectronCodexRuntimeBridge) {
        try {
            const snapshot = await bridge.getCodexRateLimits()
            if (snapshot) this.acceptSnapshot(bridge, snapshot)
        } catch {
            if (bridge === this.bridge) this.markStale()
        }
    }

    private handleConnectionChange(bridge: ElectronCodexRuntimeBridge, connected: boolean) {
        if (bridge !== this.bridge) return
        if (!connected) {
            this.markStale()
            return
        }

        void this.refresh(bridge)
    }

    private scheduleExpiration(snapshot: CodexRateLimitSnapshot, receivedAt: number) {
        if (this.expirationTimer) clearTimeout(this.expirationTimer)
        this.expirationTimer = null
        if (!snapshot.available) return
        const resetTime = firstResetTime(snapshot)
        if (resetTime === null) return
        const localResetTime = receivedAt + resetTime - snapshot.observedAt
        const delay = Math.max(0, localResetTime - Date.now())
        if (delay === 0) {
            this.markStale()
            return
        }
        this.expirationTimer = setTimeout(() => this.markStale(), delay)
    }

    private markStale() {
        if (!this.state.snapshot || this.state.stale) return

        this.setState({ ...this.state, stale: true })
    }

    private unsubscribe() {
        this.unsubscribeRateLimits?.()
        this.unsubscribeConnection?.()
        this.unsubscribeRateLimits = null
        this.unsubscribeConnection = null
        if (this.expirationTimer) clearTimeout(this.expirationTimer)
        this.expirationTimer = null
    }

    private setState(state: CodexRateLimitState) {
        if (
            state.receivedAt === this.state.receivedAt
            && state.snapshot === this.state.snapshot
            && state.stale === this.state.stale
        ) return

        this.state = state
        this.dispatchEvent(new CustomEvent('changed'))
    }
}

export const codexRateLimitService = new CodexRateLimitService()

import type { AgentConversation, AgentTokenUsage, Card, ProjectSnapshot } from '../../data/data_types'
import { sumAgentTokenUsage } from '../../../../shared/agent_usage_math.mjs'

export { sumAgentTokenUsage }

export interface AgentUsageVersion {
    name: string
    usage: AgentTokenUsage
}

export interface AgentFileChangeUsage {
    deletions: number
    insertions: number
}

export interface ProjectAgentUsage {
    archived: AgentUsageVersion
    current: AgentUsageVersion
    project: AgentTokenUsage
    releases: AgentUsageVersion[]
}

export function cardAgentTokenUsage(source: AgentConversation[] | Card): AgentTokenUsage {
    const conversations = Array.isArray(source) ? source : source.agentConversations

    return sumAgentTokenUsage(conversations.map(({ usage }) => usage))
}

/** Aggregate loaded conversations belonging to one action on one card. */
export function actionCardAgentTokenUsage(conversations: AgentConversation[], actionId: string, cardInternalId: string): AgentTokenUsage {
    const matchingUsage = conversations
        .filter((conversation) => conversation.actionId === actionId && conversation.cardInternalId === cardInternalId)
        .map(({ usage }) => usage)

    return sumAgentTokenUsage(matchingUsage)
}

/** Sum completed provider patches in one canonical conversation. */
export function conversationFileChangeUsage(conversation: AgentConversation | null): AgentFileChangeUsage | null {
    if (!conversation) return null
    let countedEvents = 0
    let deletions = 0
    let insertions = 0
    for (const entry of conversation.entries) {
        if (entry.kind !== 'event' || entry.type !== 'fileChange' || entry.status !== 'completed') continue
        const { deletions: eventDeletions, insertions: eventInsertions } = entry
        if (typeof eventDeletions !== 'number' || !Number.isSafeInteger(eventDeletions) || eventDeletions < 0) continue
        if (typeof eventInsertions !== 'number' || !Number.isSafeInteger(eventInsertions) || eventInsertions < 0) continue

        countedEvents += 1
        deletions += eventDeletions
        insertions += eventInsertions
    }

    return countedEvents > 0 ? { deletions, insertions } : null
}

function releaseName(cardPath: string, releasesFolder: string) {
    const normalizedReleasesFolder = releasesFolder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const releasesPrefix = `${normalizedReleasesFolder}/`
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')
    if (!normalizedCardPath.startsWith(releasesPrefix)) return null

    const releaseSegments = normalizedCardPath.slice(releasesPrefix.length).split('/')

    return releaseSegments.length >= 2 && releaseSegments[0].length > 0 ? releaseSegments[0] : null
}

/** Aggregate loaded agent conversations by current board, archived release, and project. */
function isInsideFolder(cardPath: string, folder: string) {
    const normalizedFolder = folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')

    return normalizedCardPath.startsWith(`${normalizedFolder}/`)
}

/** Aggregate loaded agent conversations by current board, archived cards, releases, and project. */
export function projectAgentTokenUsage(
    snapshot: ProjectSnapshot | null,
    releasesFolder: string,
    archivedFolder: string,
): ProjectAgentUsage {
    const activeCards = snapshot?.activeCards ?? []
    const backgroundCards = snapshot?.backgroundCards ?? []
    const currentUsage = sumAgentTokenUsage(activeCards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)))
    const archivedUsage = sumAgentTokenUsage(
        backgroundCards
            .filter((card) => isInsideFolder(card.path, archivedFolder))
            .map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)),
    )
    const releaseCards = new Map<string, Card[]>()

    for (const card of backgroundCards) {
        const name = releaseName(card.path, releasesFolder)
        if (!name) continue

        releaseCards.set(name, [...(releaseCards.get(name) ?? []), card])
    }
    const releases = [...releaseCards.entries()]
        .map(([name, cards]) => ({
            name,
            usage: sumAgentTokenUsage(cards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations))),
        }))
        .sort((left, right) => left.name.localeCompare(right.name))
    const project = sumAgentTokenUsage([currentUsage, archivedUsage, ...releases.map(({ usage }) => usage)])

    return {
        archived: { name: 'Archived', usage: archivedUsage },
        current: { name: 'Current', usage: currentUsage },
        project,
        releases,
    }
}

